const $=id=>document.getElementById(id);let stage=0,changed=false,clarified=false,noticeTimer=null,audioCtx=null,noise=null,gain=null,noticeIndex=0;
const form=$('order'),messages=['New pastries at the counter.','Loyalty cards available today.','Please collect receipts at the counter.'];
function target(){return changed?{drink:'Tea',milk:'No milk',size:'Small'}:{drink:'Latte',milk:'Oat milk',size:'Small'}}
function stopAudio(){if(noise){try{noise.stop()}catch{}noise=null}if(audioCtx){audioCtx.close().catch(()=>{});audioCtx=null}gain=null;$('sound').checked=false}
function refreshNotices(){clearInterval(noticeTimer);$('notice').hidden=!$('notices').checked;if($('notices').checked)noticeTimer=setInterval(()=>{$('notice').lastElementChild.textContent=messages[++noticeIndex%messages.length]},7000)}
function render(){const written=$('written').checked, vague=$('vague').checked&&!clarified;const order=changed?'Order a small iced tea with no milk.':'Order a small iced latte with oat milk.';$('task').textContent=written?order:'Keep the original order in mind. You can ask to see it again.';$('step-list').hidden=!written||stage!==2;$('instruction').textContent=changed?(vague?'“We’re out of that. Just pick the other one, same as before.”':'“Latte is unavailable. Please choose a small iced tea with no milk instead.”'):(vague?'“Pick the usual one. You know how it goes.”':'“Choose your drink, milk, and size. Take the time you need.”');form.querySelector('[value="Latte"]').disabled=changed;$('change').disabled=changed;$('change-status').textContent=changed?'Latte is unavailable. The task now uses iced tea.':'Optional: change the order during the task.';$('summary').hidden=!written;const d=new FormData(form);$('summary').textContent='Your selection: '+['drink','milk','size'].map(k=>d.get(k)||'—').join(' / ');document.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stage===stage)));$('support-note').hidden=stage!==2}
function setStage(n){if(![0,1,2].includes(n))throw Error('Invalid stage');stage=n;clarified=false;stopAudio();$('notices').checked=n===1;$('vague').checked=n===1;$('written').checked=n!==1;const titles=['Start with the task','Notice the extra demands','Make the task more accessible'];$('panel-title').textContent=titles[n];$('stage-label').textContent=['A familiar starting point','More competing information','Clearer information and choices'][n];$('panel-description').textContent=['Read the order, then make your selection. There is no timer or score.','Try one change at a time. Sound is optional and stays off until you choose it.','The task and any unavailable item stay the same. Change the support, then try again.'][n];$('feedback').textContent='This is a practice task. Nothing is purchased.';$('feedback').className='feedback';refreshNotices();render()}
document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>setStage(+b.dataset.stage));
['written','vague'].forEach(id=>$(id).onchange=()=>{clarified=false;render()});$('notices').onchange=refreshNotices;
$('clarify').onclick=()=>{clarified=true;$('written').checked=true;render()};$('change').onclick=()=>{changed=true;form.querySelectorAll('[name=drink]').forEach(i=>i.checked=false);$('feedback').textContent='Availability changed. Ask for clarification whenever you need it.';render()};form.onchange=render;
form.onsubmit=e=>{e.preventDefault();const d=new FormData(form),t=target();const ok=Object.keys(t).every(k=>d.get(k)===t[k]);$('feedback').className='feedback '+(ok?'success':'error');$('feedback').textContent=ok?'Order complete. Pause and discuss what helped you decide.':'This selection differs from the requested order. Ask for clear instructions or check the written order.'};
function quiet(){stopAudio();$('notices').checked=false;refreshNotices();$('feedback').className='feedback';$('feedback').textContent='Quiet mode. Sound and background notices are off. Continue when you are ready.'}
$('stop').onclick=quiet;document.addEventListener('keydown',e=>{if(e.key==='Escape')quiet()});document.addEventListener('visibilitychange',()=>{if(document.hidden)quiet()});
$('reset').onclick=()=>{changed=false;form.reset();setStage(0)};
$('sound').onchange=async()=>{if(!$('sound').checked){stopAudio();return}try{const Ctx=window.AudioContext||window.webkitAudioContext;audioCtx=new Ctx();await audioCtx.resume();if(!$('sound').checked||!audioCtx)return;const buf=audioCtx.createBuffer(1,audioCtx.sampleRate*3,audioCtx.sampleRate),ch=buf.getChannelData(0);let last=0;for(let i=0;i<ch.length;i++){last=(last+Math.random()*.08-.04)/1.02;ch[i]=last}noise=audioCtx.createBufferSource();noise.buffer=buf;noise.loop=true;gain=audioCtx.createGain();gain.gain.value=+$('volume').value/100;const filter=audioCtx.createBiquadFilter();filter.type='lowpass';filter.frequency.value=600;noise.connect(filter);filter.connect(gain);gain.connect(audioCtx.destination);noise.start()}catch{stopAudio();$('feedback').textContent='Audio is unavailable in this browser. You can complete the demo silently.'}};
$('volume').oninput=()=>{$('vol-label').textContent=$('volume').value+'%';if(gain&&audioCtx)gain.gain.setTargetAtTime(+$('volume').value/100,audioCtx.currentTime,.1)};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_demo_stage',description:'Select a classroom demo stage. Sound remains off. No diagnosis or score is produced.',inputSchema:{type:'object',properties:{stage:{type:'integer',enum:[0,1,2]}},required:['stage'],additionalProperties:false},execute:({stage:n})=>{setStage(n);return{stage:n,sound:'off'}}})).catch(()=>{})}catch{}}
render();

const socialStyles=document.createElement('link');socialStyles.rel='stylesheet';socialStyles.href='social.css';document.head.appendChild(socialStyles);
let socialStage=0,socialUnlocked=0,selectedImpression='',selectedRepair='';
const socialTitles=['What is your first impression?','What might each person mean?','Which response makes meaning clearer?','What changed in the interaction?'];
function setMode(mode){const social=mode==='social';$('environment-mode').hidden=social;$('social-mode').hidden=!social;$('mode-environment').setAttribute('aria-pressed',String(!social));$('mode-social').setAttribute('aria-pressed',String(social));if(social)stopAudio()}
function setSocialStage(n){if(n<0||n>socialUnlocked)return;socialStage=n;document.querySelectorAll('[data-social-stage]').forEach(b=>{const i=+b.dataset.socialStage;b.disabled=i>socialUnlocked;b.setAttribute('aria-pressed',String(i===n))});$('social-heading').textContent=socialTitles[n];$('social-counter').textContent=(n+1)+' of 4';$('dialogue').hidden=n===3;$('perspectives').hidden=n!==1;$('comparison').hidden=n!==3;$('impression-step').hidden=n!==0;$('perspective-step').hidden=n!==1;$('repair-step').hidden=n!==2;$('compare-step').hidden=n!==3}
$('mode-environment').onclick=()=>setMode('environment');$('mode-social').onclick=()=>setMode('social');
document.querySelectorAll('[data-social-stage]').forEach(b=>b.onclick=()=>setSocialStage(+b.dataset.socialStage));
document.querySelectorAll('[data-impression]').forEach(b=>b.onclick=()=>{selectedImpression=b.dataset.impression;document.querySelectorAll('[data-impression]').forEach(x=>{const chosen=x===b;x.classList.toggle('selected',chosen);x.setAttribute('aria-checked',String(chosen))});$('impression-feedback').textContent='You chose: '+selectedImpression+'. Hold that interpretation until the reveal.';$('reveal-perspectives').disabled=false});
$('reveal-perspectives').onclick=()=>{socialUnlocked=Math.max(socialUnlocked,1);setSocialStage(1)};
$('continue-repair').onclick=()=>{socialUnlocked=Math.max(socialUnlocked,2);setSocialStage(2)};
const repairMessages={hurry:'This adds pressure without clarifying the task.',ready:'This asks about readiness, but the expected response is still unclear.',explicit:'This gives one concrete request and leaves room to process it.',written:'This offers another communication channel. Ask whether it helps.'};
document.querySelectorAll('[data-repair]').forEach(b=>b.onclick=()=>{selectedRepair=b.dataset.repair;const helpful=['explicit','written'].includes(selectedRepair);document.querySelectorAll('[data-repair]').forEach(x=>{x.classList.remove('selected','helpful','unhelpful');if(x===b)x.classList.add('selected',helpful?'helpful':'unhelpful')});$('repair-feedback').textContent=repairMessages[selectedRepair]+(helpful?' You can now compare the exchange.':' Try another response that makes the next step clearer.');$('show-comparison').disabled=!helpful;if(helpful)socialUnlocked=Math.max(socialUnlocked,3);setSocialStage(2)});
$('show-comparison').onclick=()=>setSocialStage(3);
$('restart-social').onclick=()=>{socialUnlocked=0;selectedImpression='';selectedRepair='';document.querySelectorAll('[data-impression]').forEach(x=>{x.classList.remove('selected');x.setAttribute('aria-checked','false')});document.querySelectorAll('[data-repair]').forEach(x=>x.classList.remove('selected','helpful','unhelpful'));$('impression-feedback').textContent='Choose the interpretation that came to mind first.';$('repair-feedback').textContent='Try a response and notice what information it provides.';$('reveal-perspectives').disabled=true;$('show-comparison').disabled=true;setSocialStage(0)};
document.querySelectorAll('.details-body').forEach(box=>{box.innerHTML=box.innerHTML.replace('Autism Spectrum Disorder Disorder','Autism Spectrum Disorder')});
const zhDetails=document.querySelector('details[lang="zh-Hant"] .details-body');if(zhDetails)zhDetails.insertAdjacentHTML('beforeend','<h3>Social Interaction Mode｜約 4–6 分鐘</h3><p><b>第一印象：</b>請觀眾先選一個直覺判斷，再問：「你從哪一句話或哪個停頓形成這個印象？」</p><p><b>揭露雙方視角：</b>顧客可能正在拆解問題的意思，店員則可能以為「the usual」是在降低壓力。兩人可能都帶著善意，但使用了不同線索。</p><p><b>選擇修復語句：</b>比較四種回應。具體說明下一步，或提供書面選項，通常比催促更能降低猜測；實際使用時仍要詢問當事人偏好。</p><p><b>前後比較：</b>問：「行為本身改變了，還是我們對行為的解釋與溝通方式改變了？」Double empathy 是理解互相誤讀的研究框架，不代表所有互動都會遵循同一規律；較大型的 2025 預先註冊研究也顯示結果會隨情境而變化。</p>');
setSocialStage(0);setMode('environment');

const conversation=$('dialogue').parentElement;
const sceneArt=document.createElement('div');sceneArt.className='scene-illustrations';sceneArt.setAttribute('aria-label','Illustrated café setting');sceneArt.innerHTML='<figure><img src="assets/irasutoya/cafe-staff.png" alt="Illustration of a café staff member standing behind the counter"><figcaption>BARISTA SIDE</figcaption></figure><div class="scene-link" aria-hidden="true"><span>ORDER</span><b>↔</b><span>INTERPRET</span></div><figure><img src="assets/irasutoya/customers-menu.png" alt="Illustration of customers reading restaurant menus"><figcaption>CUSTOMER SIDE</figcaption></figure>';
conversation.insertBefore(sceneArt,$('dialogue'));
const artCredit=document.createElement('p');artCredit.className='art-credit';artCredit.innerHTML='Context illustrations: <a href="https://www.irasutoya.com/" target="_blank" rel="noopener">いらすとや</a>. The characters set the scene; they do not depict a diagnosis.';conversation.insertBefore(artCredit,$('dialogue'));
const sourceList=document.querySelector('details .details-body ul');if(sourceList){const li=document.createElement('li');li.innerHTML='<a href="https://www.irasutoya.com/p/terms.html" target="_blank" rel="noopener">いらすとや: usage terms</a> — two official illustrations used as supporting design elements: <a href="https://www.irasutoya.com/2018/07/blog-post_579.html" target="_blank" rel="noopener">café staff</a> and <a href="https://www.irasutoya.com/2015/08/blog-post_89.html" target="_blank" rel="noopener">customers choosing a menu</a>.';sourceList.appendChild(li)}
